//! Drawing-only inventory of currently unsupported code77 binding prerequisites.
use sketchpad_rs::document::{Document,Kind,records};
use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};
fn collect(p:&Path,v:&mut Vec<PathBuf>){if p.is_dir(){for e in fs::read_dir(p).unwrap().flatten(){if !e.file_type().unwrap().is_symlink(){collect(&e.path(),v)}}}else if p.extension().is_some_and(|x|x.eq_ignore_ascii_case("gsp")){v.push(p.into())}}
fn n(b:&[u8],a:usize)->usize{u32::from_le_bytes(b[a..a+4].try_into().unwrap())as usize}
fn name(k:&Kind)->String{format!("{k:?}").split(|c:char|!c.is_alphanumeric()).next().unwrap().into()}
fn main(){let mut files=vec![];collect(Path::new("../gsp-rs"),&mut files);files.sort();let mut cats:BTreeMap<String,(usize,BTreeSet<PathBuf>,Vec<String>)>=BTreeMap::new();let mut total=0;
for path in files{let b=fs::read(&path).unwrap();let Ok(doc)=Document::from_bytes(&b,None)else{continue};let Ok(rs)=records(&b)else{continue};for o in &doc.objects{if !matches!(o.kind,Kind::Unsupported(77)){continue}total+=1;let Some(at)=o.header_offset else{continue};let Some(start)=rs.iter().position(|r|r.kind==0x7d0&&r.data.start==at)else{continue};let Some(end)=(start..rs.len()).find(|&i|rs[i].kind==0x7d7)else{continue};let Some(raw)=rs[start..=end].iter().find(|r|r.kind==0x7d2).map(|r|&b[r.data.clone()])else{continue};let base=doc.objects.iter().position(|x|x.page==o.page).unwrap();let ids:Vec<_>=raw[4..].chunks_exact(4).map(|c|n(c,0)+base).collect();let mut key=format!("header{:?} refs{}",&b[at+6..at+10],ids.len());let mut detail=format!("{} global{} page{} refs{:?}",path.display(),o.id,o.page,ids);
if ids.len()==2{if let(Some(source),Some(parent))=(doc.objects.get(ids[0].wrapping_sub(1)),doc.objects.get(ids[1].wrapping_sub(1))){let carried=match &parent.kind{Kind::MappedPointIteration{carried,..}=>carried.contains(&source.id),_=>false};key=format!("source={} parent={} carried={} header={:?}",name(&source.kind),name(&parent.kind),carried,&b[at+6..at+10]);detail.push_str(&format!(" sourcekind={:?} parentkind={:?}",source.kind,parent.kind));if carried{println!("READY {}",detail)}}}let cat=cats.entry(key).or_default();cat.0+=1;cat.1.insert(path.clone());if cat.2.len()<5{cat.2.push(detail)}}}
println!("TOTAL {total}");for(k,(n,files,ex))in cats{println!("COUNT {n} files{} {k}",files.len());for e in ex{println!("EX {e}")}}}
